#include "average_pooling_3d_custom_tiling.h"
#include "register/op_def_registry.h"

namespace {
inline int64_t floor_div(int64_t a, int64_t b) {
    return a / b;
}
inline int64_t out_dim(int64_t in, int64_t k, int64_t s, int64_t p) {
    return floor_div(in + 2 * p - k, s) + 1;
}
}

namespace optiling {
const uint32_t BLOCK_DIM = 8;
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    AveragePooling3dCustomTilingData tiling;
    auto inShape = context->GetInputShape(0)->GetOriginShape();
    int64_t n = inShape.GetDim(0);
    int64_t c = inShape.GetDim(1);
    int64_t d = inShape.GetDim(2);
    int64_t h = inShape.GetDim(3);
    int64_t w = inShape.GetDim(4);

    int64_t k = context->GetIntAttr("kernel_size");
    int64_t s = context->GetIntAttr("stride");
    int64_t p = context->GetIntAttr("padding");

    int64_t od = out_dim(d, k, s, p);
    int64_t oh = out_dim(h, k, s, p);
    int64_t ow = out_dim(w, k, s, p);

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(static_cast<uint32_t>(n));
    tiling.set_c(static_cast<uint32_t>(c));
    tiling.set_d(static_cast<uint32_t>(d));
    tiling.set_h(static_cast<uint32_t>(h));
    tiling.set_w(static_cast<uint32_t>(w));
    tiling.set_kd(static_cast<uint32_t>(k));
    tiling.set_sd(static_cast<uint32_t>(s));
    tiling.set_pd(static_cast<uint32_t>(p));
    tiling.set_od(static_cast<uint32_t>(od));
    tiling.set_oh(static_cast<uint32_t>(oh));
    tiling.set_ow(static_cast<uint32_t>(ow));

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    int64_t n = x_shape->GetDim(0);
    int64_t c = x_shape->GetDim(1);
    int64_t d = x_shape->GetDim(2);
    int64_t h = x_shape->GetDim(3);
    int64_t w = x_shape->GetDim(4);

    int64_t k = context->GetIntAttr("kernel_size");
    int64_t s = context->GetIntAttr("stride");
    int64_t p = context->GetIntAttr("padding");

    auto calc = [](int64_t in, int64_t k, int64_t s, int64_t p) {
        return (in + 2 * p - k) / s + 1;
    };
    int64_t od = calc(d, k, s, p);
    int64_t oh = calc(h, k, s, p);
    int64_t ow = calc(w, k, s, p);

    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDim(0, n);
    y_shape->SetDim(1, c);
    y_shape->SetDim(2, od);
    y_shape->SetDim(3, oh);
    y_shape->SetDim(4, ow);
    return GRAPH_SUCCESS;
}
